from requests.adapters import HTTPAdapter, _urllib3_request_context
from requests.models import PreparedRequest
a = HTTPAdapter()
p = PreparedRequest()
p.prepare(method='GET', url='http://127.0.0.1:54897/basic-auth/user/pass')
host_params, pool_kwargs = a.build_connection_pool_key_attributes(p, True, None)
assert host_params == {'scheme': 'http', 'host': '127.0.0.1', 'port': 54897}
assert pool_kwargs == {'cert_reqs': 'CERT_REQUIRED'}
_, pk_false = _urllib3_request_context(p, False, None, a.poolmanager)
assert pk_false == {'cert_reqs': 'CERT_NONE'}
_, pk_path = _urllib3_request_context(p, '/path/to/ca.pem', None, a.poolmanager)
assert pk_path == {'ca_certs': '/path/to/ca.pem', 'cert_reqs': 'CERT_REQUIRED'}
